        firstSeenAt: prev && Number.isFinite(prev.firstSeenAt) ? prev.firstSeenAt : nowMs, lastSeenAt: nowMs,
        runs: prev && Number.isInteger(prev.runs) && prev.runs >= 0 ? prev.runs + 1 : 1 };
